            "startTimeOffsetSeconds": self._start_time_offset_seconds,
            "endTimeOffsetSeconds": self._end_time_offset_seconds,
            "skipToDate": _dt_to_ms(self._skip_to_date),
            "maxCatchupRuns": self._max_catchup_runs,
        }

